// Core Domain Types

export type Color = 'w' | 'b' | 'r' | 'y' | 'g';
export type PieceSymbol = 'p' | 'n' | 'b' | 'r' | 'q' | 'k';

export interface Piece {
  color: Color;
  type: PieceSymbol;
  isDead?: boolean; // For 4-player when king is captured
}

export type Square = string; // e.g. "e4", "a1", "14-14"

export type BoardRecord = Record<Square, Piece>;

export interface MathTrial {
  question: string;
  answer: number;
  expiresAt: number;
}

export interface PlayerExtState {
  spells: string[];
  activeTrial?: MathTrial;
}

export interface GameState {
  version: number;
  variant: string;
  status: 'lobby' | 'playing' | 'draw' | 'win' | 'aborted';
  turn: Color;
  board: BoardRecord;
  history: Command[];
  clocks?: Record<Color, number>; // Milliseconds remaining
  players: Partial<Record<Color, string>>; // Player IDs
  winner?: Color | null; // null for draw
  lastMove?: { from: Square; to: Square; piece: Piece }; // For UI highlights
  fen?: string; // Optional canonical FEN if standard 8x8
  
  // Extensions
  playerStates?: Record<string, PlayerExtState>;
  frozenSquares?: Record<string, number>;
}

// Commands (Intents from client)
export type CommandType = 'move' | 'use_power' | 'resign' | 'offer_draw' | 'accept_draw' | 'request_trial' | 'answer_trial' | 'cast_spell';

export interface BaseCommand {
  type: CommandType;
  playerColor: Color;
  version: number; // State version this command was issued against
}

export interface MoveCommand extends BaseCommand {
  type: 'move';
  from: Square;
  to: Square;
  promotion?: PieceSymbol;
}

export interface TrialCommand extends BaseCommand {
  type: 'request_trial' | 'answer_trial';
  answer?: number;
}

export interface CastCommand extends BaseCommand {
  type: 'cast_spell';
  spellName: string;
  target: string;
}

export type Command = MoveCommand | TrialCommand | CastCommand | BaseCommand;

// Events (Emitted by reducer, though state is primary, events help client animations)
export type EventType = 'move' | 'capture' | 'check' | 'game_over' | 'power_used';

export interface BaseEvent {
  type: EventType;
}

export interface MoveEvent extends BaseEvent {
  type: 'move';
  from: Square;
  to: Square;
  piece: Piece;
}

export interface CaptureEvent extends BaseEvent {
  type: 'capture';
  square: Square;
  captured: Piece;
  capturedBy?: Piece; // Optional to support Fog
}

export type GameEvent = MoveEvent | CaptureEvent | BaseEvent;

// PlayerView (What a specific player sees)
export interface PlayerView {
  version: number;
  variant: string;
  status: GameState['status'];
  turn: Color;
  board: BoardRecord; // Redacted for Fog
  clocks?: Record<Color, number>;
  myColor: Color;
  winner?: Color | null;
  lastMove?: { from: Square; to: Square; piece: Piece };
}

// Ruleset Interface
export interface Ruleset {
  variant: string;
  getInitialState(players: Partial<Record<Color, string>>): GameState;
  applyCommand(state: GameState, command: Command): { newState: GameState; events: GameEvent[]; error?: string };
  getPlayerView(state: GameState, playerColor: Color): PlayerView;
}
